const model = {
    _init:false,
    _raceFiles:[], // an array of fileRec
    showHalfPolar:true,
    showDotsOnPolar:false,
    polar:null,
    raceTimeframes: null,
    polarFileId:null,
    _polarfileCache: new Map(),
    selectedPolarName: null,
    showingPolarFile: false,
    overlayPolar: null,

    init: async function() {
        if (!this._init) {
            await gd.ensurePolarFolderAsync();
            this._init = true;
            return false;
        }
        return this._init;
    },
    setSelectedPolarName: function(name) {
        this.selectedPolarName = name;
    },
    setOverlayPolar: function(polar) {
        this.overlayPolar = polar;
    },
    getOverlayPolar: function() {
        return this.overlayPolar;
    },
    getSelectedPolarCacheItemAsync: async function() {
        return this.getNamedPolarCacheItemAsync(this.selectedPolarName);
    },
    getNamedPolarCacheItemAsync: async function(name) {
        let polarCached = this._polarfileCache.get(name);
        if (polarCached == undefined) {
            polarCached = await this.loadPolarAsync(name);
        }
        return polarCached;
    },    
    getCachedPolarFilesAsync: async function() {
        return this._polarfileCache;
    },
    
    loadPolarAsync: async function (name) {
        let item = {
            filename: name,
            saved: true,
            polar: null
        }
        try {
            //TODO - change to use DataStore.loadPolarFromGDriveById - quicker
            const polarObj = await DataStore.loadPolarByNameAsync(name);
            if (polarObj) {
                item.polar = polarObj.polarStruct;
                item.id = polarObj.fileId;
            }
        } catch (e) {
            console.log(e);
        }
        this._polarfileCache.set(name, item);
        console.log('loaded: polar',name);
        return item;
    },
    deletePolarAsync: async function(name) {
        let polarCached = this._polarfileCache.get(name);
        if (polarCached != undefined) {
            await gd.deleteFileAsync(polarCached.id);
        }
    },
    loadRaceList: async function(loadRaceFn, loadAnnotationsFn) {
        const result = await gd.listFolderContentsAsync(gd.getDataFolder());
        const resultInfo = await gd.listFolderContentsAsync(await gd.ensureAppDataFolderAsync());
        if (result != null && result.files != undefined && resultInfo != null && resultInfo.files != undefined) {
            result.files.push(...resultInfo.files);
            const races = DataStore.extractRaceFiles(result.files);
            if (races != null && races.length > 0) {
                this._raceFiles = races;
                for(const fileRec of this._raceFiles) {
                    this.loadFileAnnotations(fileRec, loadRaceFn, loadAnnotationsFn);
                }
            } else {
                alert('No race files with corresponding labeled sections found');
            }
        } else {
            alert('No race files found.');
        }
        console.log("Race list:",this._raceFiles);
    },
    updatePolarFromSelection: function() {
        const timeframes = [];
        for (const fileRec of this._raceFiles) {
            if (fileRec.annotationsInUse != undefined) {
                fileRec.annotationsInUse.forEach(x => {
                    timeframes.push(...sliceTimeframesBy(fileRec.vessel.data, x));
                });
            }
        }
        this.raceTimeframes = timeframes;
        this.racePolar = c.createPolar(timeframes, true).polarStruct;
    },
    savePolarAs: async function(fileName) {
        if (!fileName.toLocaleLowerCase().endsWith(".polar.json")) {
            fileName = fileName+".polar.json";
        }
        let polarStruct;
        if (this.isPolarFileShowing()) {
            const item = await this.getSelectedPolarCacheItemAsync();
            polarStruct = item.polar;
        } else {
            let races = [];
            for(let r of this._raceFiles) {
                if (r.annotationsInUse != null && r.annotationsInUse.size > 0) {
                    races.push({
                        annotationsInUse: r.annotationsInUse,
                        raceName: r.raceName,
                    });
                }
            }
            console.log(races);
            polarStruct = this.racePolar;
            polarStruct.races = races;
        }
        const polar = new Polar(polarStruct, fileName, null);
        await c.dataStore.savePolarToGDrive(polar, c.setLoadingMessage);
        this.racePolarFileId = polar.fileId;
    },
    saveSelectedPolar: async function() {
        const item = await this.getSelectedPolarCacheItemAsync();
        const polar = new Polar(item.polar, item.filename, item.id);
        await c.dataStore.savePolarToGDrive(polar, c.setLoadingMessage);
    },
    loadPolarAsyncList: async function() {
        const polarFolder = await gd.ensurePolarFolderAsync();
        let result = await gd.listFolderContentsAsync(polarFolder);
        if (result == null || result.files == undefined)
            return [];

        const files = result.files.filter(f => f.name.endsWith(".polar.json"));
        for (const f of files) {
            this.loadPolarAsync(f.name);
        }
        return files;
    },
    async loadFileAnnotations(fileRec, loadRaceFn, whenLoadedFn) {
        const div = loadRaceFn(fileRec);
        const info = await DataStore.loadInfoFromGDriveById(fileRec.infoFile.id, fileRec.infoFile.name);
        if (info != null) {
            fileRec.raceInfo = info;
            info.orderRaceInfoAnnotations();
            fileRec.annotationSequence = info.getAnnotationSequence();
            whenLoadedFn(div, fileRec);
        }
    },
    setShowingPolarFile: function(flag) {
        this.showingPolarFile=flag;
    },
    isPolarFileShowing: function() {
        return this.showingPolarFile;
    }

};

