export async function showAsync() {
    const initAlready = await model.init();
    if (!initAlready) {
        map = new maplibregl.Map({
            container: 'pb-map',
            style: {
                version: 8,
                sources: {
                    'osm': {
                        type: 'raster',
                        tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
                        tileSize: 256,
                        maxzoom: 19
                    }
                },
                layers: [{
                    id: 'osm',
                    type: 'raster',
                    source: 'osm'
                }]
            },
            center: [-98, 38],
            zoom: 2,
            maxZoom: 19
        });
        overlay = new MapboxOverlay({ layers: [] });
        map.addControl(overlay);

        loadRaceListHtmlAsync();
        loadPolarAsyncListHtml();
        initTableArrowListener();
    }
    if (c.raceData() != null) {
        const data = c.raceData().sail().data;
        if (data != null) {
            showTrack(data.vessel);
            showSelectedRacePolar();
        }
    }
}

