async function showSelectedPolarFileAsync() {
    const item = await model.getSelectedPolarCacheItemAsync();
    const overlayPolar = model.getOverlayPolar()
    const polar = item.polar;
    if (polar != null) {
        model.setShowingPolarFile(true);
        showPolarComponents(polar, overlayPolar, null,item.filename, item.saved);
        setButtonState();
    }
}

function setButtonState() {
    if (model.isPolarFileShowing()) {
        polarDataRight.classList.add("selected");
        polarDataLeft.classList.remove("selected");
        polarBuilderSaveButton.style.display="block";
    } else {
        polarDataLeft.classList.add("selected");
        polarDataRight.classList.remove("selected");
        polarBuilderSaveButton.style.display="none";
    }
}


