async function loadRaceListHtmlAsync() {
    const sidebar = document.getElementById('pb-sidebar');
    model.loadRaceList(
        (fileRec) => {
            const fileDiv = document.createElement('div');
            fileDiv.className = "pb-filename";
            fileDiv.textContent = fileRec.raceName;
            fileDiv.id = `fileDiv-${fileRec.raceName}`;
            sidebar.appendChild(fileDiv);
            return fileDiv;
        },
        (fileDiv, fileRec) => {
            for(const a of fileRec.annotationSequence) {
                const aDiv = document.createElement('div');
                aDiv.className = 'pb-section';
                aDiv.textContent = summarizeAnnotation(a);
                aDiv.addEventListener("click", (e) => {
                    loadAndHighlightTrackSegmentAsync(aDiv, fileRec, a);
                });
                fileDiv.appendChild(aDiv);
            }
        });
}

function summarizeAnnotation(a) {
    let result = '- ';
    for(let i=0;i<a.labels.length;i++) {
        result += a.labels[i];
        if (i < a.labels.length - 1) {
            result += '/';
        }
    }
    result += a.notes == null || a.notes.length == 0? '' : ` (${a.notes})`;
    return result;
}

