/***************************************** POLAR SEGMENT MAP ******************************************/

function showTrack(vessel, annotation) {
    const coords = vessel.data.map(f => [f.lon, f.lat]);
    const layers = [
        new PathLayer({
            id: 'track',
            data: [{ path: coords }],
            getPath: d => d.path,
            getColor: [128, 128, 128],
            getWidth: 2,
            widthMinPixels: 2
        })
    ];
    
    if (annotation) {
        const highlightCoords = sliceCoordsForAnnotation(vessel.data, annotation);
        if (highlightCoords) {
            layers.push(new PathLayer({
                id: 'highlight',
                data: [{ path: highlightCoords }],
                getPath: d => d.path,
                getColor: [255, 0, 0],
                getWidth: 2,
                widthMinPixels: 2
            }));
        }
    }
    
    overlay.setProps({ layers });
    
    setTimeout(() => {
        const bounds = coords.reduce((b, c) => {
            b[0] = Math.min(b[0], c[0]);
            b[1] = Math.min(b[1], c[1]);
            b[2] = Math.max(b[2], c[0]);
            b[3] = Math.max(b[3], c[1]);
            return b;
        }, [Infinity, Infinity, -Infinity, -Infinity]);
        map.fitBounds(bounds, { padding: 40 });
    }, 200);
}

function sliceTimeframesBy(timeframes, annotation) {
    const startIdx = timeframes.findIndex(x => x.t.isSameOrAfter(annotation.begin_ts));
    const endIdx = timeframes.findIndex(x => x.t.isSameOrAfter(annotation.end_ts));
    if (startIdx >= 0 && endIdx >= 0) {
        return timeframes.slice(startIdx,endIdx+1);
    }
    return null;
}

function sliceCoordsForAnnotation(data, annotation) {
    const startIdx = data.findIndex(x => x.t.isSameOrAfter(annotation.begin_ts));
    const endIdx = data.findIndex(x => x.t.isSameOrAfter(annotation.end_ts));
    if (startIdx >= 0 && endIdx >= 0) {
        return data.slice(startIdx, endIdx + 1).map(f => [f.lon, f.lat]);
    }
    return null;
}

/***************************************** POLAR EDITOR ******************************************/

function setPolarName(polarName) {
    const title = document.getElementById("polarEditorTitle");
    title.innerHTML = polarName;
}

function showTable(polarStruct, polarName, polarSaved) {
    setPolarName(polarName);
    flagPolarSaved(polarSaved);
    const table = document.getElementById("pb-table");
    table.innerHTML = '';
    const thead = document.createElement('thead');
    let th = document.createElement('th');
    th.innerText='';
    th.className='pb-th';
    thead.appendChild(th);
    polarStruct.tws.forEach(tws => {
        th = document.createElement('th');
        th.innerText=tws;
        th.className='pb-th';
        thead.appendChild(th);
    });
    table.appendChild(thead);
    // const windSpeed = polarStruct.tws[windIdx];
    for(let angleIdx=0;angleIdx < polarStruct.twa.length;angleIdx++) {
        let tr = document.createElement('tr');
        let td = document.createElement('td');
        td.className='pb-td';
        td.innerText = polarStruct.twa[angleIdx].twa;
        tr.appendChild(td);
        for (let windIdx=0;windIdx<polarStruct.tws.length;windIdx++) {
            td = document.createElement('td');
            td.className='pb-td';
            const input = document.createElement('input');
            input.type='text';
            input.value=polarStruct.twa[angleIdx].boatSpeed[windIdx];
            input.addEventListener("focus", (e) => {
                polar.pointHighlight(PLOTLY_DIV, polarStruct.twa[angleIdx].twa, polarStruct.twa[angleIdx].boatSpeed[windIdx]);
            });
            input.addEventListener("blur", (e) => {
                polar.clearPointHighlight(PLOTLY_DIV);
            });

            input.addEventListener("change", async (e) => {
                // angleIdx windIdx
                polarStruct.twa[angleIdx].boatSpeed[windIdx] = e.target.value;
                showPolar(polarStruct, model.getOverlayPolar());
                const item = await model.getNamedPolarCacheItemAsync(polarName);
                item.saved = false;
                flagPolarSaved(false);
            });
            td.appendChild(input);
            tr.appendChild(td);
        }
        table.appendChild(tr);
    }
}

function flagPolarSaved(status) {
    if (status)
        document.getElementById('polarEditorTitle').classList.remove('polar-title-unsaved');
    else
        document.getElementById('polarEditorTitle').classList.add('polar-title-unsaved');
}

function initTableArrowListener() {
    const table = document.getElementById('pb-table');

  table.addEventListener('keydown', function (e) {
    const key = e.key;
    if (!['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) return;

    const current = e.target;
    if (current.tagName !== 'INPUT') return;

    const td = current.closest('td');
    const tr = current.closest('tr');
    if (!td || !tr) return;

    const cellIndex = td.cellIndex;
    const rowIndex = tr.rowIndex;

    const rows = Array.from(table.rows);
    let target;

    switch (key) {
      case 'ArrowRight':
        target = td.nextElementSibling?.querySelector('input');
        break;
      case 'ArrowLeft':
        target = td.previousElementSibling?.querySelector('input');
        break;
      case 'ArrowUp':
        if (rowIndex > 0) {
          target = rows[rowIndex - 1].cells[cellIndex]?.querySelector('input');
        }
        break;
      case 'ArrowDown':
        if (rowIndex < rows.length - 1) {
          target = rows[rowIndex + 1].cells[cellIndex]?.querySelector('input');
        }
        break;
    }

    if (target) {
      e.preventDefault(); // prevent cursor move in text field
      target.focus();
    }
  });
}

