document.getElementById("polarBuilderExport").addEventListener("click", async () => {
    // Get the currently selected polar
    const item =await model.getSelectedPolarCacheItemAsync();
    const polarData = item.polar;
    if (!polarData) {
        alert("No polar selected.");
        return;
    }
    const polarText = printPolarAsCSV(polarData);

    const popup = window.open("", "Polar Export", "width=800,height=600");
    if (popup) {
        popup.document.open(); // Clear previous content
        popup.document.write("<pre style='white-space:pre-wrap;word-break:break-all;'>" + 
            polarText + "</pre>");
        popup.document.title = "Polar JSON Export";
        popup.document.close();
    } else {
        alert("Popup blocked. Please allow popups for this site.");
    }
});

function printPolarAsCSV(polarStruct) {
    let csv = 'TWA/TWS';
    polarStruct.tws.forEach(tws => {
        csv += ',' + tws;
    });
    csv += '\n';
    for (let angleIdx = 0; angleIdx < polarStruct.twa.length; angleIdx++) {
        let row = polarStruct.twa[angleIdx].twa;
        for (let windIdx = 0; windIdx < polarStruct.tws.length; windIdx++) {
            let v = polarStruct.twa[angleIdx].boatSpeed[windIdx];
            v = v == null ? '':v;
            row += ',' + v;
        }
        csv += row + '\n';
    }
    return csv;
}

