let _lastAuthSuccess = true;
export async function initGoogleDriveAsync(tokensuccesscallback) {
  try {
    // Auto-trigger login if not authenticated
    // removing as this just creates a cycle.
    // if (!c.sharedFileMode() && isTokenExpiredOrInvalid()) {
    //   console.log("initGoogleDriveAsync: click(), sharing:",c.sharedFileMode(), "expired:",isTokenExpiredOrInvalid());
    //   document.getElementById("g_id_signin").click();
    // }

    if (c.sharedFileMode())
      return;

    if (typeof google === 'undefined') {
      alert("Please log in to Google Drive.");
      return;
    }

    tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: clientId,
      scope: 'https://www.googleapis.com/auth/drive.file',
      callback: async (tokenResponse) => {
        console.log('initGoogleDriveAsync: Auth response:', tokenResponse);
        if (tokenResponse.error == null && parseInt(tokenResponse.expires_in) > 600) {
          accessToken = tokenResponse.access_token;
          const expiresIn = tokenResponse.expires_in;
          localStorage.setItem(LOCAL_STORAGE.ACCESS_TOKEN, accessToken);
          localStorage.setItem(LOCAL_STORAGE.ACCESS_TOKEN_EXPIRY, Date.now() + expiresIn * 1000); // Save expiry time
          console.log('initGoogleDriveAsync: Access token obtained:', accessToken);
          // document.getElementById('g_id_signin').style.display = 'none';
          _lastAuthSuccess = true;
          await ensureDataFolderAsync();
          tokensuccesscallback();
        } else {
          console.log("initGoogleDriveAsync: requesting auth with consent");
          console.log("initGoogleDriveAsync: Last response: error",tokenResponse.error, "expires in: ", tokenResponse.expires_in);
          _lastAuthSuccess = false;
          setTimeout(loadTokenOrPromptAuthAsync, 1000);
          if (_intervalId > 0)
            clearInterval(_intervalId);
        }
      }
    });
    accessToken = localStorage.getItem(LOCAL_STORAGE.ACCESS_TOKEN);
    if (accessToken == undefined) {
      console.log("initGoogleDriveAsync: accessToken undefined");
      tokenClient.requestAccessToken({prompt: 'none'});
    } else {
      await ensureDataFolderAsync();
    }
    await loadTokenOrPromptAuthAsync(tokensuccesscallback);
    gapi.load('picker', { 'callback': onPickerApiLoad });
  } catch (e) {
    notifyError(`Failure initalising google drive: `,e); 
  }
};

let _intervalId = -1;
async function loadTokenOrPromptAuthAsync(tokensuccesscallback) {
  if (c.sharedFileMode())
    return;

  if (!_lastAuthSuccess) {
    console.log("initGoogleDriveAsync: last login fail, request token 'consent'");
    tokenClient.requestAccessToken({prompt: 'consent'});
  } else if (isTokenExpiredOrInvalid()) {
    const prompt = /Mobi|Android|iPhone|iPad/i.test(navigator.userAgent) ? 'select_account' : 'none';
    console.log("initGoogleDriveAsync: token expired, request token prompt:", prompt);
    tokenClient.requestAccessToken({prompt});
  } else if (tokensuccesscallback) {
    console.log("initGoogleDriveAsync: tokensuccesscallback exists, calling");
    await ensureDataFolderAsync();
    tokensuccesscallback();
    console.log("initGoogleDriveAsync: tokensuccesscallback finished");
  }
  // _intervalId = setInterval(loadTokenOrPromptAuth, 60000); // Check every 10 sec
}

function isTokenExpiredOrInvalid() {
  const expiryTime = localStorage.getItem(LOCAL_STORAGE.ACCESS_TOKEN_EXPIRY);
  accessToken = localStorage.getItem(LOCAL_STORAGE.ACCESS_TOKEN);
  return isInvalidStorage(accessToken) || isInvalidStorage(expiryTime) || Date.now() > expiryTime - 5*60000;
}

function isInvalidStorage(val) {
  return val == undefined || val == null || val == "undefined";
}


