async function loadFolder(folderName, localStorageObjKey, parentId, attemptCount=0) {
  let folder = JSON.parse(localStorage.getItem(localStorageObjKey));
  if (!folder || !folder.id) {
    if (attemptCount <= 0) {
      try {
        folder = await findFolderByNameAsync(folderName,parentId);
        if (folder == null) {
          folder = await createFolderAsync(folderName, parentId);
          console.info(`Created data folder:`+folderName);
        }
        if (localStorageObjKey !== null) {
          localStorage.setItem(localStorageObjKey, JSON.stringify(folder));
        }
      } catch (error) {
        console.info(error);
        alert("Error accessing or creating ",folderName," folder. Please log in to Google Drive.");
        loadFolder(folderName,localStorageObjKey,parentId, attemptCount + 1); // second attempt
      }
    }
  } else {
    console.info('Loaded folder from local storage:'+folderName+', id:'+folder.id+', parend id:'+parentId);
  }
  return folder;
}

