export async function uploadFilesToFolderAsync(files) {
  if (!isReady()) {
    alert('Google Drive not ready!');
    return null;
  }

  return new Promise((resolve) => {
    const view = new google.picker.DocsView()
      .setIncludeFolders(true)
      .setSelectFolderEnabled(true)
      .setMode(google.picker.DocsViewMode.LIST);

    const picker = new google.picker.PickerBuilder()
      .addView(view)
      .setOAuthToken(accessToken)
      .setDeveloperKey(developerKey)
      .setAppId(appId)
      .setCallback(async (data) => {
        if (data.action === google.picker.Action.PICKED) {
          const folder = data.docs[0];
          const uploadedFiles = [];
          for (const file of files) {
            const fileId = await uploadFileToGDriveAsync(file.name, file.type, file, {id: folder.id});
            if (fileId) {
              uploadedFiles.push({name: file.name, id: fileId});
            }
          }
          resolve(uploadedFiles);
        } else if (data.action === google.picker.Action.CANCEL) {
          resolve([]);
        }
      })
      .build();
    picker.setVisible(true);
  });
}

export async function drivePickAndDownloadFileAsync(folder, okFn, errFn = (response) => {console.log(response)}) {
  if (isReady()) {
    const view = new google.picker.DocsView()
    .setIncludeFolders(true)
    .setSelectFolderEnabled(false)
    .setMode(google.picker.DocsViewMode.LIST)
    .setMimeTypes('application/json,text/plain,application/gzip')
    // .setEnableDrives(true)
    ;
    if (folder != null) {
      view.setParent(folder.id)
    }
    
    const picker = new google.picker.PickerBuilder()
    .addView(view)
    .setOAuthToken(accessToken)
    .setDeveloperKey(developerKey)
    .setAppId(appId)
    //.enableFeature(google.picker.Feature.MINE_ONLY)
    // .enableFeature(google.picker.Feature.MULTISELECT_ENABLED)
    .setCallback((data) => {
      if (data.action === google.picker.Action.PICKED) {
        fetchFileContent(data.docs, okFn, errFn);
      } else if (data.action === google.picker.Action.CANCEL) {
        okFn({});
      }
    })
    .build();
    picker.setVisible(true);
  }
}

async function fetchFileContent(docs, okFn, errFn) {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${docs[0].id}?alt=media`, {
    headers: new Headers({ 'Authorization': 'Bearer ' + accessToken })
  });
  
  if (res.ok) {
    okFn(res, docs[0]);
  } else {
    errFn(res)
  }
}



export async function uploadFileToGDriveAsync(fileName, mimeType, fileContent, folder) {
  console.info('Saving file: ${fileName} mime: ${mimeType} into ${folder.name}');
  await loadTokenOrPromptAuthAsync();
  if (!isReady()) {
    alert('Google Drive not ready!');
    return null;
  }
  
  if (!folder || !folder.id) {
    alert('Please select a folder for uploading.');
    return null;
  }

  const fileBlob = fileContent instanceof Blob ? fileContent : new Blob([fileContent], { type: mimeType });

  const metadata = {
    name: fileName,
    mimeType: mimeType,
    parents: [folder.id]
  };

  const form = new FormData();
  form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
  form.append('file', fileBlob);

  const res = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
    method: 'POST',
    headers: new Headers({ 'Authorization': 'Bearer ' + accessToken }),
    body: form
  });

  const result = await res.json();

  if (res.ok && result.id) {
    console.info(`Uploaded ${fileName}`);
    return result.id;
  } else {
    console.error('Upload failed:', result);
    return null;
  }
}

export async function updateFileContentAsync(fileId, newContent, mimeType = 'application/json') {
  await loadTokenOrPromptAuthAsync();
  const fileBlob = new Blob([newContent], { type: mimeType });

  const metadata = {
    mimeType: mimeType
  };

  const form = new FormData();
  //meta data blob uses needs it's own mime type
  form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
  form.append('file', fileBlob);

  const response = await fetch(`https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=multipart`, {
    method: 'PATCH',
    headers: new Headers({ 'Authorization': 'Bearer ' + accessToken }),
    body: form,
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`Failed to update file: ${error}`);
  }

  const result = await response.json();
  console.log('File updated successfully:', result);
  return result;
}

async function findFileByNameAndParentAsync(fileName, parentId, accessToken) {
  const query = `name='${fileName}' and '${parentId}' in parents and trashed=false`;
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&fields=files(id,name)`, {
    headers: {
      Authorization: `Bearer ${accessToken}`
    }
  });

  const data = await res.json();
  if (!data.files.length) throw new Error('File not found');
  return data.files[0]; // Return the first match
}


export async function fetchFileContentAsync(fileId) {
  await loadTokenOrPromptAuthAsync();
  const headers = {Authorization: `Bearer ${accessToken}`};
  const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`, {
    headers: headers
  });

  if (!response.ok) {
    throw new Error('Failed to fetch file content');
  }

  return await response.arrayBuffer();
}

