async function findFolderByNameAsync(folderName, parentId) {
  let query;
  if (parentId == null) {
    query = encodeURIComponent(
      `name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false`
    );
  } else {
    query = encodeURIComponent(
      `name = '${folderName}' and mimeType = 'application/vnd.google-apps.folder' and '${parentId}' in parents and trashed = false`
    );
  }

  const url = `https://www.googleapis.com/drive/v3/files?q=${query}&fields=files(id,name)`;

  try {
    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    const data = await response.json();
    if (!data.files || data.files.length === 0) {
      console.log(`No folder named '${folderName}' found in parent ${parentId}`);
      return null;
    }
    
    // Return the first matching folder (or modify to return all if needed)
    return data.files[0];
  } catch (err) {
    console.error('Error finding folder:', err);
    return null;
  }
}

