export async function getFilePermissions(fileId) {
  await loadTokenOrPromptAuthAsync();
  const res = await fetch(
    `https://www.googleapis.com/drive/v3/files/${fileId}/permissions?fields=permissions(id,type,role)`,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      }
    }
  );

  if (!res.ok) {
    const error = await res.json();
    throw new Error(`Failed to get file permissions: ${error.error?.message || res.statusText}`);
  }

  const result = await res.json();
  return result.permissions || [];
}

/**
 * Checks if a file is already shared with public read access
 * @param {string} fileId - Google Drive file ID
 * @returns {Promise<boolean>}
 */
export async function isFileShared(fileId) {
  const permissions = await getFilePermissions(fileId);
  return permissions.some(permission =>
    permission.type === 'anyone' && permission.role === 'reader'
  );
}

/**
 * Creates a permission for anyone with the link to read the file
 * @param {string} fileId - Google Drive file ID
 * @returns {Promise<Object>} - Created permission object
 */
export async function createPublicReadPermission(fileId) {
  await loadTokenOrPromptAuthAsync();
  
  const res = await fetch(
    `https://www.googleapis.com/drive/v3/files/${fileId}/permissions`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        type: 'anyone',
        role: 'reader',
        allowFileDiscovery: false
      })
    }
  );

  if (!res.ok) {
    const error = await res.json();
    throw new Error(`Failed to create public read permission: ${error.error?.message || res.statusText}`);
  }

  const result = await res.json();
  return result;
}

